  /**
   * allFilerTasks iterates over GET /v1/dedicatedCloud/{serviceName}/filer/{filerId}/task (List datastore tasks).
   *
   * It lists the IDs with {@link DedicatedCloudApi.listFilerTasks}, then gets each object with
   * {@link DedicatedCloudApi.getFilerTask}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action pccVMware:apiovh:filer/task/get.
   *
   * @param serviceName - Domain of the service
   * @param filerId - Filer Id
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.DedicatedCloudTask}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.dedicatedCloud.allFilerTasks(serviceName, filerId)) console.log(item);
   */
  allFilerTasks(
    serviceName: string,
    filerId: number,
    params?: {
      /** Filter the value of name property (like) */
      name?: string | undefined;
      /** Filter the value of state property (=) */
      state?: models.DedicatedCloudTaskStateEnum | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.DedicatedCloudTask> {
    return this._each(
      () => this.listFilerTasks(serviceName, filerId, params, options),
      (listedId) => this.getFilerTask(serviceName, filerId, listedId, options),
    );
  }

